# Anchor = each language's ACTUAL last key line (real Unicode in the file),
# insert AFTER it so the new keys land inside that language's block.
ANCHORS = [
    ('    "admin.authNote": "Protect this page by setting ADMIN_USER and ADMIN_PASSWORD in your environment.",', EN),
    ('    "admin.authNote": "设置环境变量 ADMIN_USER 与 ADMIN_PASSWORD 即可保护此页面。",', ZH),
    ('    "nav.blog": "ブログ",', JA),
    ('    "pricing.month": "/mois",', FR),
    ('    "admin.authNote": "Schützen Sie diese Seite, indem Sie ADMIN_USER und ADMIN_PASSWORD in Ihrer Umgebung setzen.",', DE),
]

with open(PATH, "r", encoding="utf-8") as f:
    lines = f.readlines()

for anchor, block in ANCHORS:
    block_lines = [b + "\n" for b in block.rstrip("\n").split("\n")]
    found = False
    for i, line in enumerate(lines):
        if line.rstrip("\n") == anchor:
            lines[i + 1:i + 1] = block_lines
            found = True
            break
    if not found:
        raise SystemExit("ANCHOR NOT FOUND: " + anchor[:50])

with open(PATH, "w", encoding="utf-8") as f:
    f.writelines(lines)

print("OK: inserted all home keys into correct language blocks")
